/**
 * The pure decisions the surface generator makes, separated from the file it writes.
 *
 * Everything here is a total function over the installed SDK's own text, so the generated registry can be
 * regenerated byte-identically and each rule can be tested without a network call or a temp directory.
 *
 * ## Why the SDK's own operation key is the naming authority
 *
 * Every operation in `@datadog/datadog-api-client` names itself once, in the string it hands
 * `getServer` — `v1.DowntimesApi.listDowntimes`. That string is what the client uses to pick a server, it
 * is unique across the whole package (measured: 1,735 call sites, 1,735 distinct keys), and it survives a
 * version bump unless Datadog renames the operation, which is exactly when a registry row SHOULD move. A
 * name derived from the path would collide the moment two methods share one path, and a name invented here
 * would drift from the thing it points at.
 */

/** Which of the SDK's two versioned packages declares an operation. Also the prefix of every surface name. */
export type DatadogSpec = "v1" | "v2";

/**
 * How a collection is walked, decided from the query parameters the operation declares.
 *
 * Datadog pages five incompatible ways across its two versions and this reduces them to the shape a walker
 * has to implement. `limit-only` is a CAP rather than a walk and is reported as such, so a reducer never
 * mistakes one page for a census — the same distinction `jumpcloud/surfaceNaming.ts` draws, and for the
 * same reason.
 */
export type DatadogPaging = "cursor" | "offset" | "page-number" | "limit-only" | "none";

/**
 * Split an identifier on camelCase and non-alphanumeric runs into a lower-case, hyphenated fragment.
 *
 * @param identifier the SDK's own identifier, in any casing
 * @returns the kebab-case fragment, with no leading or trailing hyphen
 * @internal
 */
export function kebab({ identifier }: { identifier: string }): string {
  return identifier
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .replace(/[^a-zA-Z0-9]+/g, "-")
    .toLowerCase()
    .replace(/^-+|-+$/g, "");
}

/**
 * The full surface name a caller passes instead of a URL.
 *
 * The `Api` suffix on the class half is dropped because every class carries it, so keeping it would put
 * the same four characters in 1,735 names and distinguish nothing.
 *
 * @param operationKey the SDK's own `<spec>.<Class>Api.<operation>` key, verbatim
 * @returns the collision-tested surface name
 * @internal
 */
export function surfaceName({ operationKey }: { operationKey: string }): string {
  return kebab({ identifier: operationKey.replace(/Api\./, ".") });
}

/**
 * The atlas kind an operation contributes to, taken from the first segment of its path that names a thing.
 *
 * The provider's own vocabulary rather than an invented one, so a reader who knows the Datadog console
 * knows the kind. The version prefix is stripped because `v1` and `v2` are two ways to reach one kind —
 * `/api/v1/monitor` and `/api/v2/monitor/...` are both `monitor` — and an atlas that split them would put
 * the same platform data in the catalogue twice, which `kit/contract.ts` exists to prevent.
 *
 * `/api/unstable/` is stripped the same way. An unstable endpoint is a REACH fact, recorded on the row's
 * own `stability`, never a separate kind: the owner's ruling is that an undocumented or unstable endpoint
 * that works is a usable source, so hiding one behind its own kind would bury exactly what the atlas is
 * for.
 *
 * @param path the SDK's own path template, `{brace}` parameters intact
 * @returns the first segment that is not a version prefix, or `root` for a path with none
 * @internal
 */
export function kindOf({ path }: { path: string }): string {
  const named = path
    .split("/")
    .find(
      (segment) =>
        segment.length > 0 && segment !== "api" && segment !== "v1" && segment !== "v2" && segment !== "unstable",
    );
  if (named === undefined) {
    return "root";
  }
  return named;
}

/**
 * Whether an operation is reached at a path Datadog itself marks unstable.
 *
 * A fact for a reader to weigh, never a gate — `kit/contract.ts` says the same about `documented`, and for
 * the same reason: an atlas that refused an unstable endpoint would be refusing the surface most likely to
 * carry something nobody knew existed.
 *
 * @param path the SDK's own path template
 * @returns `true` when the path sits under Datadog's `unstable` prefix
 * @internal
 */
export function isUnstablePath({ path }: { path: string }): boolean {
  return path.startsWith("/api/unstable/");
}

/**
 * The parameter patterns each paging shape is recognised by, in the order of decreasing strength that
 * {@link pagingOf} applies.
 *
 * Held as one table rather than as four inline regexes because two functions read it and they must agree:
 * {@link pagingOf} names the SHAPE and {@link pagingParameterOf} names the exact parameter that drives it.
 * Split across two copies, a walker could be handed `cursor` as the shape and an offset parameter to send —
 * and a walker sending the wrong parameter gets page one back forever while reporting a complete walk.
 * `limit-only` is deliberately last because it is a CAP rather than a walk.
 * @internal
 */
const PAGING_PATTERNS: readonly { readonly shape: DatadogPaging; readonly pattern: RegExp }[] = [
  { pattern: /cursor|next_record_id|continuation_token|page_token|page\[token\]|next_page/i, shape: "cursor" },
  { pattern: /^(page\[offset\]|offset|id_offset)$/i, shape: "offset" },
  { pattern: /^(page\[number\]|page_number|page)$/i, shape: "page-number" },
  { pattern: /^(page\[size\]|page\[limit\]|page_size|per_page|limit|count)$/i, shape: "limit-only" },
];

/**
 * The parameter names that cap a page's SIZE, whatever shape walks it.
 *
 * Separate from {@link PAGING_PATTERNS} because a size cap is orthogonal to a walk: a `cursor` operation
 * usually also takes a `page[size]`, and a live pass wants to send both. The same pattern appears in both
 * tables — as the `limit-only` SHAPE when a cap is the only thing on offer, and as a size cap otherwise —
 * and that overlap is the intended reading rather than a duplication to factor out.
 * @internal
 */
const PAGE_SIZE_PATTERN = /^(page\[size\]|page\[limit\]|page_size|per_page|limit|count)$/i;

/**
 * Decide how a collection is paged from the query parameter names the operation declares.
 *
 * Order matters, and it is the order of decreasing strength. A cursor is the only shape that survives
 * concurrent writes, so an operation offering one is walked that way even when it also offers an offset.
 * A bare `limit` is last because it is not a walk at all.
 *
 * @param parameterNames every query parameter the operation sets, exactly as the SDK spells it
 * @returns the paging shape this operation is walked with
 * @internal
 */
export function pagingOf({ parameterNames }: { parameterNames: readonly string[] }): DatadogPaging {
  for (const { shape, pattern } of PAGING_PATTERNS) {
    if (parameterNames.some((name) => pattern.test(name))) {
      return shape;
    }
  }
  return "none";
}

/**
 * The exact query parameter that drives this operation's walk, as the SDK spells it.
 *
 * A live pass cannot send a paging SHAPE — it has to send a NAME, and Datadog pages under at least eight
 * different ones across its two versions (`page[cursor]`, `next_record_id`, `page[offset]`, `start`,
 * `page`, …). Recording the shape alone would leave a walker guessing.
 *
 * @param parameterNames every query parameter the operation sets, exactly as the SDK spells it
 * @returns the driving parameter's own name, or `null` when the operation does not walk
 * @internal
 */
export function pagingParameterOf({ parameterNames }: { parameterNames: readonly string[] }): string | null {
  for (const { pattern } of PAGING_PATTERNS) {
    const matched = parameterNames.find((name) => pattern.test(name));
    if (matched !== undefined) {
      return matched;
    }
  }
  return null;
}

/**
 * The query parameter that caps one page's size, as the SDK spells it.
 *
 * @param parameterNames every query parameter the operation sets, exactly as the SDK spells it
 * @returns the size parameter's own name, or `null` when the operation declares none
 * @internal
 */
export function pageSizeParameterOf({ parameterNames }: { parameterNames: readonly string[] }): string | null {
  const matched = parameterNames.find((name) => PAGE_SIZE_PATTERN.test(name));
  if (matched === undefined) {
    return null;
  }
  return matched;
}
